<?php
require_once __DIR__.'/config/db.php';require_once __DIR__.'/config/auth.php';require_role('studente');
$pageTitle='Presenze';$active='presenze';$id=$_SESSION['user_id'];$mese=$_GET['mese']??date('Y-m');
$stmt=$pdo->prepare("SELECT p.data,p.stato,p.note,m.nome materia FROM presenze p LEFT JOIN materie m ON m.id=p.materia_id WHERE p.studente_id=? AND DATE_FORMAT(p.data,'%Y-%m')=? ORDER BY p.data DESC");$stmt->execute([$id,$mese]);$rows=$stmt->fetchAll();
$total=count($rows);$presenti=count(array_filter($rows,fn($r)=>$r['stato']==='presente'));$assenti=count(array_filter($rows,fn($r)=>$r['stato']==='assente'));$giust=count(array_filter($rows,fn($r)=>$r['stato']==='giustificato'));$percent=$total?round($presenti/$total*100):0;
require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><main class="main"><header class="topbar"><h1>Presenze</h1><div class="user-menu"><a href="logout.php">Esci</a></div></header><section class="content"><div class="page-head"><h2>Registro presenze</h2><p>Consulta la tua frequenza e lo storico mensile.</p></div><form method="get" class="card form-card"><div class="field"><label>Seleziona mese</label><input type="month" name="mese" value="<?=e($mese)?>"></div><button class="btn">Filtra</button></form><div class="grid section"><article class="card"><div class="stat-label">Frequenza</div><div class="stat-number"><?=$percent?>%</div><div class="muted">Nel mese selezionato</div></article><article class="card"><div class="stat-label">Presenti</div><div class="stat-number"><?=$presenti?></div><div class="muted">Su <?=$total?> registrazioni</div></article><article class="card"><div class="stat-label">Assenti</div><div class="stat-number"><?=$assenti?></div><div class="muted">Non giustificati</div></article><article class="card"><div class="stat-label">Giustificati</div><div class="stat-number"><?=$giust?></div><div class="muted">Assenze giustificate</div></article></div><div class="section"><h3>Storico</h3><div class="table-wrap"><table><thead><tr><th>Data</th><th>Materia</th><th>Stato</th><th>Note</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="4" class="empty">Nessuna presenza per il mese selezionato.</td></tr><?php endif;foreach($rows as $r): ?><tr><td><?=date('d/m/Y',strtotime($r['data']))?></td><td><?=e($r['materia']??'-')?></td><td class="<?= $r['stato']==='presente'?'good':'warn' ?>"><?=e(ucfirst($r['stato']))?></td><td><?=e($r['note']??'-')?></td></tr><?php endforeach?></tbody></table></div></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>